const test = require('node:test');
const assert = require('node:assert/strict');
const { normalizeLines } = require('../newlines.cjs');
test('treats CRLF as one ending', () => {
  assert.equal(normalizeLines('rack7
rack8'), 'rack7
rack8');
  assert.equal(normalizeLines('AB
C
D'), 'A
B
C
D
');
  assert.equal(normalizeLines('
'), '

');
  assert.equal(normalizeLines('

'), '

');
  assert.equal(normalizeLines('A
B'), 'A
B');
  assert.equal(normalizeLines(''), '');
  const once = normalizeLines('x
yz');
  assert.equal(normalizeLines(once), once);
});

